"""Contact sheet for substitute teachers."""

from typing import List

from rosterkit.models import Student
from rosterkit.errors import ProjectError

def _check_students(students: List[Student]) -> None:
    if not students:
        raise ProjectError("cannot build a contact sheet from no students")
    for item in students:
        if not item.email:
            raise ProjectError(f"no email for {item.display_name}")

def _align(cells: List[tuple]) -> List[str]:
    widths = [max(len(text) for text in column) for column in zip(*cells)]
    return [
        "  ".join(text.ljust(wide) for text, wide in zip(line, widths)).rstrip()
        for line in cells
    ]

def format_contacts(students: List[Student]) -> List[str]:
    """Rows of name, section and email, sorted by display name."""
    _check_students(students)
    ordered = sorted(students, key=lambda item: item.display_name)
    return _align([(item.display_name, item.section, item.email) for item in ordered])

