# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.errors import ProjectError
from rosterkit.contacts import format_contacts

def make_student(last, email="x@example.com"):
    return Student("1", last, "Pat", "A", email)

class ContactTests(unittest.TestCase):
    def test_rows_sorted_and_aligned(self):
        rows = format_contacts([make_student("Zed", "z@e.com"), make_student("Bo", "b@e.com")])
        self.assertEqual(rows, ["Bo, Pat   A  b@e.com", "Zed, Pat  A  z@e.com"])

    def test_missing_email_names_student(self):
        with self.assertRaisesRegex(ProjectError, "Bo, Pat"):
            format_contacts([make_student("Bo", None)])

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            format_contacts([])
